CREATE TABLE public.quotation_work_order_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), inspection_id uuid NOT NULL REFERENCES public.inspections(id) ON DELETE CASCADE, work_order_id uuid NOT NULL REFERENCES public.inspection_work_orders(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','awaiting_approval','resolved','cancelled')), reason text NOT NULL DEFAULT '', created_by uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), report_version_id uuid REFERENCES public.inspection_report_versions(id) ON DELETE SET NULL, submitted_at timestamptz, resolved_at timestamptz, submitter_name text);
GRANT SELECT ON public.quotation_work_order_revisions TO authenticated; GRANT ALL ON public.quotation_work_order_revisions TO service_role;
ALTER TABLE public.quotation_work_order_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY revision_internal_read ON public.quotation_work_order_revisions FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.inspections i WHERE i.id=inspection_id AND public.user_has_market(auth.uid(),i.market) AND (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'executive') AND i.executive_id=auth.uid()))));
CREATE UNIQUE INDEX quotation_revision_one_active ON public.quotation_work_order_revisions(inspection_id) WHERE status IN ('draft','awaiting_approval');
CREATE TABLE public.quotation_work_order_changes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), revision_id uuid NOT NULL REFERENCES public.quotation_work_order_revisions(id) ON DELETE CASCADE, repair_item_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('add','modify','remove')), before_json jsonb, after_json jsonb, decision text CHECK(decision IN ('accepted','rejected')), comment text, decided_at timestamptz, applied_at timestamptz, UNIQUE(revision_id,repair_item_id));
GRANT SELECT ON public.quotation_work_order_changes TO authenticated; GRANT ALL ON public.quotation_work_order_changes TO service_role;
ALTER TABLE public.quotation_work_order_changes ENABLE ROW LEVEL SECURITY;
CREATE POLICY changes_internal_read ON public.quotation_work_order_changes FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.quotation_work_order_revisions r WHERE r.id=revision_id));
ALTER TABLE public.inspection_repair_items ADD COLUMN is_archived boolean NOT NULL DEFAULT false;
ALTER TABLE public.inspection_work_order_items ADD COLUMN is_archived boolean NOT NULL DEFAULT false;
ALTER TABLE public.inspection_work_order_items ADD COLUMN quotation_paused boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN public.inspection_work_order_items.quotation_paused IS 'Affected work paused while investor approval of a quotation revision is outstanding.';
CREATE OR REPLACE FUNCTION public.authorize_quotation_revision(p_inspection_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.inspections%ROWTYPE; BEGIN SELECT * INTO i FROM public.inspections WHERE id=p_inspection_id; IF NOT FOUND OR NOT public.user_has_market(auth.uid(),i.market) OR NOT (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'executive') AND i.executive_id=auth.uid())) THEN RAISE EXCEPTION 'not_authorized'; END IF; IF i.inspection_type NOT IN ('captacion','check_out') THEN RAISE EXCEPTION 'invalid_inspection_type'; END IF; END $$;
REVOKE ALL ON FUNCTION public.authorize_quotation_revision(uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.start_quotation_revision(p_inspection_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w public.inspection_work_orders%ROWTYPE; rid uuid; BEGIN PERFORM public.authorize_quotation_revision(p_inspection_id); SELECT * INTO w FROM public.inspection_work_orders WHERE inspection_id=p_inspection_id FOR UPDATE; IF NOT FOUND OR w.status NOT IN ('open','in_progress','rejected','contractor_rejected') THEN RAISE EXCEPTION 'work_order_not_open'; END IF; SELECT id INTO rid FROM public.quotation_work_order_revisions WHERE inspection_id=p_inspection_id AND status IN ('draft','awaiting_approval'); IF rid IS NOT NULL THEN RETURN rid; END IF; INSERT INTO public.quotation_work_order_revisions(inspection_id,work_order_id,created_by) VALUES(p_inspection_id,w.id,auth.uid()) RETURNING id INTO rid; RETURN rid; END $$;
CREATE OR REPLACE FUNCTION public.save_quotation_revision_change(p_revision_id uuid,p_repair_item_id uuid,p_kind text,p_values jsonb,p_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.quotation_work_order_revisions%ROWTYPE; old_row jsonb; new_row jsonb; item_id uuid:=COALESCE(p_repair_item_id,gen_random_uuid()); cid uuid; w public.inspection_work_orders%ROWTYPE; BEGIN SELECT * INTO r FROM public.quotation_work_order_revisions WHERE id=p_revision_id; IF NOT FOUND THEN RAISE EXCEPTION 'revision_not_found'; END IF; PERFORM public.authorize_quotation_revision(r.inspection_id); SELECT * INTO w FROM public.inspection_work_orders WHERE id=r.work_order_id FOR UPDATE; SELECT * INTO r FROM public.quotation_work_order_revisions WHERE id=p_revision_id FOR UPDATE; IF r.status<>'draft' OR w.status NOT IN ('open','in_progress','rejected','contractor_rejected') THEN RAISE EXCEPTION 'revision_not_editable'; END IF; IF p_kind NOT IN ('add','modify','remove') THEN RAISE EXCEPTION 'invalid_change'; END IF; IF p_kind<>'add' THEN SELECT to_jsonb(x)-'updated_at' INTO old_row FROM public.inspection_repair_items x WHERE x.id=item_id AND x.inspection_id=r.inspection_id AND NOT x.is_archived FOR UPDATE; IF old_row IS NULL THEN RAISE EXCEPTION 'repair_not_found'; END IF; IF EXISTS(SELECT 1 FROM public.inspection_work_order_items WHERE repair_item_id=item_id AND (status='done' OR is_archived)) THEN RAISE EXCEPTION 'completed_work_is_immutable'; END IF; ELSE IF EXISTS(SELECT 1 FROM public.inspection_repair_items WHERE id=item_id) THEN RAISE EXCEPTION 'invalid_new_item'; END IF; END IF; IF p_kind<>'remove' THEN new_row:=COALESCE(old_row,'{}'::jsonb)||jsonb_build_object('id',item_id,'inspection_id',r.inspection_id,'inspection_section_id',p_values->>'inspection_section_id','title_snapshot',trim(p_values->>'title_snapshot'),'description_snapshot',p_values->>'description_snapshot','quantity',(p_values->>'quantity')::numeric,'unit_price',(p_values->>'unit_price')::numeric,'contractor_unit_price',(p_values->>'contractor_unit_price')::numeric,'payer_role',p_values->>'payer_role','payment_nature',COALESCE(p_values->>'payment_nature','required'),'unit',COALESCE(p_values->>'unit','serv'),'pricing_type','fixed','is_pending_quote',false,'is_archived',false); IF COALESCE(new_row->>'title_snapshot','')='' OR length(new_row->>'title_snapshot')>500 OR COALESCE((new_row->>'quantity')::numeric,0)<=0 OR COALESCE((new_row->>'unit_price')::numeric,-1)<0 OR COALESCE((new_row->>'contractor_unit_price')::numeric,-1)<0 OR COALESCE(new_row->>'payer_role','') NOT IN ('owner','tenant') OR new_row->>'payment_nature' NOT IN ('required','optional') OR NOT EXISTS(SELECT 1 FROM public.inspection_sections WHERE id=(new_row->>'inspection_section_id')::uuid AND inspection_id=r.inspection_id) THEN RAISE EXCEPTION 'invalid_repair_values'; END IF; IF p_kind='modify' AND (old_row->>'title_snapshot',old_row->>'description_snapshot',old_row->>'quantity',old_row->>'unit_price',old_row->>'contractor_unit_price',old_row->>'payer_role',old_row->>'payment_nature',old_row->>'unit',old_row->>'inspection_section_id') IS NOT DISTINCT FROM (new_row->>'title_snapshot',new_row->>'description_snapshot',new_row->>'quantity',new_row->>'unit_price',new_row->>'contractor_unit_price',new_row->>'payer_role',new_row->>'payment_nature',new_row->>'unit',new_row->>'inspection_section_id') THEN RAISE EXCEPTION 'no_changes'; END IF; END IF; INSERT INTO public.quotation_work_order_changes(revision_id,repair_item_id,kind,before_json,after_json) VALUES(r.id,item_id,p_kind,old_row,new_row) ON CONFLICT(revision_id,repair_item_id) DO UPDATE SET kind=EXCLUDED.kind,before_json=EXCLUDED.before_json,after_json=EXCLUDED.after_json RETURNING id INTO cid; UPDATE public.quotation_work_order_revisions SET reason=trim(COALESCE(p_reason,'')),updated_at=now() WHERE id=r.id; RETURN cid; END $$;
CREATE OR REPLACE FUNCTION public.discard_quotation_revision(p_revision_id uuid,p_change_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.quotation_work_order_revisions%ROWTYPE; BEGIN SELECT * INTO r FROM public.quotation_work_order_revisions WHERE id=p_revision_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'revision_not_found'; END IF; PERFORM public.authorize_quotation_revision(r.inspection_id); IF r.status<>'draft' THEN RAISE EXCEPTION 'revision_not_editable'; END IF; IF p_change_id IS NULL THEN UPDATE public.quotation_work_order_revisions SET status='cancelled',updated_at=now() WHERE id=r.id; ELSE DELETE FROM public.quotation_work_order_changes WHERE id=p_change_id AND revision_id=r.id; END IF; END $$;
CREATE OR REPLACE FUNCTION public.submit_quotation_revision(p_revision_id uuid,p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.quotation_work_order_revisions%ROWTYPE; w public.inspection_work_orders%ROWTYPE; c record; v public.inspection_report_versions%ROWTYPE; payload jsonb; sections jsonb; section jsonb; repairs jsonb; rr jsonb; mapped jsonb; result jsonb; owner_total numeric:=0; tenant_total numeric:=0; d numeric:=0; tax numeric:=0; base numeric; owner_d numeric; tenant_d numeric; BEGIN SELECT * INTO r FROM public.quotation_work_order_revisions WHERE id=p_revision_id; IF NOT FOUND THEN RAISE EXCEPTION 'revision_not_found'; END IF; PERFORM public.authorize_quotation_revision(r.inspection_id); PERFORM 1 FROM public.inspections WHERE id=r.inspection_id FOR UPDATE; SELECT * INTO w FROM public.inspection_work_orders WHERE id=r.work_order_id FOR UPDATE; SELECT * INTO r FROM public.quotation_work_order_revisions WHERE id=p_revision_id FOR UPDATE; IF r.status<>'draft' OR w.status NOT IN ('open','in_progress','rejected','contractor_rejected') THEN RAISE EXCEPTION 'revision_not_editable'; END IF; IF length(trim(COALESCE(p_reason,'')))<3 THEN RAISE EXCEPTION 'revision_reason_required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.quotation_work_order_changes WHERE revision_id=r.id) THEN RAISE EXCEPTION 'revision_has_no_changes'; END IF; FOR c IN SELECT * FROM public.quotation_work_order_changes WHERE revision_id=r.id LOOP IF c.kind<>'add' THEN SELECT to_jsonb(x)-'updated_at' INTO rr FROM public.inspection_repair_items x WHERE x.id=c.repair_item_id FOR UPDATE; IF rr IS DISTINCT FROM c.before_json THEN RAISE EXCEPTION 'revision_conflict'; END IF; IF EXISTS(SELECT 1 FROM public.inspection_work_order_items WHERE repair_item_id=c.repair_item_id AND (status='done' OR is_archived)) THEN RAISE EXCEPTION 'completed_work_is_immutable'; END IF; END IF; END LOOP; SELECT * INTO v FROM public.inspection_report_versions WHERE inspection_id=r.inspection_id AND audience='owner' AND status='published' ORDER BY version_number DESC LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'published_quotation_required'; END IF; payload:=v.normalized_payload-'quotation_revision_id'-'quotation_revision_reason'; sections:='[]'::jsonb; FOR section IN SELECT jsonb_build_object('id',id,'title',section_title) FROM public.inspection_sections WHERE inspection_id=r.inspection_id ORDER BY sort_order LOOP repairs:='[]'::jsonb; FOR rr IN SELECT COALESCE(ch.after_json,to_jsonb(x)) FROM public.inspection_repair_items x LEFT JOIN public.quotation_work_order_changes ch ON ch.revision_id=r.id AND ch.repair_item_id=x.id WHERE x.inspection_id=r.inspection_id AND NOT x.is_archived AND x.visible_to_owner AND COALESCE(ch.kind,'')<>'remove' UNION ALL SELECT after_json FROM public.quotation_work_order_changes WHERE revision_id=r.id AND kind='add' LOOP IF rr->>'inspection_section_id'=section->>'id' THEN base:=CASE WHEN COALESCE((rr->>'is_pending_quote')::boolean,false) THEN 0 ELSE (rr->>'quantity')::numeric*(rr->>'unit_price')::numeric END; mapped:=jsonb_build_object('id',rr->>'id','name',rr->>'title_snapshot','description',rr->>'description_snapshot','quantity',rr->'quantity','unit',rr->>'unit','unit_price',rr->'unit_price','subtotal',base,'payer_role',rr->>'payer_role','payment_nature',rr->>'payment_nature','is_pending_quote',COALESCE((rr->>'is_pending_quote')::boolean,false)); repairs:=repairs||jsonb_build_array(mapped); IF rr->>'payer_role'='owner' THEN owner_total:=owner_total+base; ELSE tenant_total:=tenant_total+base; END IF; END IF; END LOOP; sections:=sections||jsonb_build_array(COALESCE((SELECT elem FROM jsonb_array_elements(payload->'sections') elem WHERE elem->>'id'=section->>'id' LIMIT 1),section)||jsonb_build_object('repairs',repairs)); END LOOP; base:=owner_total+tenant_total; IF payload->'discount' IS NOT NULL THEN IF payload->'discount'->>'type'='percentage' THEN d:=base*COALESCE((payload->'discount'->>'value')::numeric,0)/100; ELSE d:=COALESCE((payload->'discount'->>'value')::numeric,(payload->'discount'->>'amount')::numeric,0); END IF; END IF; d:=least(base,greatest(d,0)); owner_d:=CASE WHEN base=0 THEN 0 ELSE d*owner_total/base END; tenant_d:=d-owner_d; IF COALESCE((payload->'tax_config'->>'enabled')::boolean,false) THEN tax:=round((base-d)*COALESCE((payload->'tax_config'->>'percentage')::numeric,0)/100); END IF; payload:=payload||jsonb_build_object('sections',sections,'budget_total',base,'quotation_revision_id',r.id,'quotation_revision_reason',trim(p_reason),'quotation_totals',jsonb_build_object('subtotal',base,'owner',owner_total,'tenant',tenant_total,'discount',d,'tax',tax,'total',base-d+tax)); IF payload->'discount' IS NOT NULL AND payload->'discount'<>'null'::jsonb THEN payload:=jsonb_set(payload,'{discount}',payload->'discount'||jsonb_build_object('amount',d,'amount_owner',owner_d,'amount_tenant',tenant_d)); END IF; result:=public.publish_quotation_version(r.inspection_id,payload); SELECT * INTO v FROM public.inspection_report_versions WHERE inspection_id=r.inspection_id AND audience='owner' AND is_latest; UPDATE public.quotation_work_order_revisions SET status='awaiting_approval',reason=trim(p_reason),report_version_id=v.id,submitted_at=now(),updated_at=now() WHERE id=r.id; UPDATE public.inspection_work_order_items SET quotation_paused=true WHERE work_order_id=w.id AND repair_item_id IN(SELECT repair_item_id FROM public.quotation_work_order_changes WHERE revision_id=r.id AND kind<>'add'); INSERT INTO public.inspection_audit_log(inspection_id,action,performed_by,note) VALUES(r.inspection_id,'quotation_revision_submitted',auth.uid(),trim(p_reason)); RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.get_quotation_revision_public(p_property_id text,p_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.quotation_work_order_revisions%ROWTYPE; data jsonb; BEGIN SELECT rev.* INTO r FROM public.quotation_work_order_revisions rev JOIN public.inspection_report_versions v ON v.id=rev.report_version_id JOIN public.inspections i ON i.id=rev.inspection_id WHERE i.property_id=p_property_id AND v.public_token=p_token AND v.audience='owner' AND v.is_latest AND v.status='published'; IF NOT FOUND THEN RETURN NULL; END IF; SELECT jsonb_agg(jsonb_build_object('id',c.id,'repair_item_id',c.repair_item_id,'kind',c.kind,'before',CASE WHEN c.before_json IS NULL THEN NULL ELSE jsonb_build_object('title_snapshot',c.before_json->>'title_snapshot','description_snapshot',c.before_json->>'description_snapshot','quantity',c.before_json->'quantity','unit',c.before_json->>'unit','unit_price',c.before_json->'unit_price','payer_role',c.before_json->>'payer_role') END,'after',CASE WHEN c.after_json IS NULL THEN NULL ELSE jsonb_build_object('title_snapshot',c.after_json->>'title_snapshot','description_snapshot',c.after_json->>'description_snapshot','quantity',c.after_json->'quantity','unit',c.after_json->>'unit','unit_price',c.after_json->'unit_price','payer_role',c.after_json->>'payer_role') END,'decision',c.decision,'comment',c.comment,'applied_at',c.applied_at) ORDER BY c.id) INTO data FROM public.quotation_work_order_changes c WHERE revision_id=r.id; RETURN jsonb_build_object('id',r.id,'status',r.status,'reason',r.reason,'submitted_at',r.submitted_at,'submitter_name',r.submitter_name,'changes',COALESCE(data,'[]'::jsonb)); END $$;
CREATE OR REPLACE FUNCTION public.submit_quotation_revision_decisions(p_property_id text,p_token text,p_submitter_name text,p_decisions jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.quotation_work_order_revisions%ROWTYPE; w public.inspection_work_orders%ROWTYPE; c public.quotation_work_order_changes%ROWTYPE; dec jsonb; rr jsonb; vals public.inspection_repair_items%ROWTYPE; BEGIN SELECT rev.* INTO r FROM public.quotation_work_order_revisions rev JOIN public.inspection_report_versions v ON v.id=rev.report_version_id JOIN public.inspections i ON i.id=rev.inspection_id WHERE i.property_id=p_property_id AND v.public_token=p_token AND v.audience='owner' AND v.is_latest AND v.status='published'; IF NOT FOUND THEN RAISE EXCEPTION 'revision_not_found'; END IF; PERFORM 1 FROM public.inspections WHERE id=r.inspection_id FOR UPDATE; SELECT * INTO w FROM public.inspection_work_orders WHERE id=r.work_order_id FOR UPDATE; SELECT * INTO r FROM public.quotation_work_order_revisions WHERE id=r.id FOR UPDATE; IF r.status<>'awaiting_approval' THEN RAISE EXCEPTION 'revision_already_answered'; END IF; IF w.status NOT IN ('open','in_progress','rejected','contractor_rejected') THEN RAISE EXCEPTION 'work_order_not_open'; END IF; IF length(trim(COALESCE(p_submitter_name,'')))<2 THEN RAISE EXCEPTION 'submitter_name_required'; END IF; IF jsonb_typeof(p_decisions) IS DISTINCT FROM 'array' OR jsonb_array_length(p_decisions)<>(SELECT count(*) FROM public.quotation_work_order_changes WHERE revision_id=r.id) OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(p_decisions) x)<>jsonb_array_length(p_decisions) THEN RAISE EXCEPTION 'invalid_decisions'; END IF; FOR c IN SELECT * FROM public.quotation_work_order_changes WHERE revision_id=r.id FOR UPDATE LOOP SELECT x INTO dec FROM jsonb_array_elements(p_decisions) x WHERE x->>'id'=c.id::text; IF dec IS NULL OR COALESCE(dec->>'decision','') NOT IN ('accepted','rejected') THEN RAISE EXCEPTION 'invalid_decisions'; END IF; IF c.kind<>'add' THEN SELECT to_jsonb(x)-'updated_at' INTO rr FROM public.inspection_repair_items x WHERE id=c.repair_item_id FOR UPDATE; IF rr IS DISTINCT FROM c.before_json THEN RAISE EXCEPTION 'revision_conflict'; END IF; IF EXISTS(SELECT 1 FROM public.inspection_work_order_items WHERE repair_item_id=c.repair_item_id AND status='done') THEN RAISE EXCEPTION 'completed_work_is_immutable'; END IF; END IF; IF dec->>'decision'='accepted' THEN IF c.kind='remove' THEN UPDATE public.inspection_work_order_items SET is_archived=true,quotation_paused=false WHERE work_order_id=w.id AND repair_item_id=c.repair_item_id; UPDATE public.inspection_repair_items SET is_archived=true,updated_by=r.created_by WHERE id=c.repair_item_id; ELSE vals:=jsonb_populate_record(NULL::public.inspection_repair_items,c.after_json); IF c.kind='add' THEN INSERT INTO public.inspection_repair_items(id,inspection_id,inspection_section_id,title_snapshot,description_snapshot,quantity,unit,pricing_type,unit_price,contractor_unit_price,payer_role,payment_nature,visible_to_owner,created_by,updated_by) VALUES(c.repair_item_id,r.inspection_id,vals.inspection_section_id,vals.title_snapshot,vals.description_snapshot,vals.quantity,vals.unit,vals.pricing_type,vals.unit_price,vals.contractor_unit_price,vals.payer_role,vals.payment_nature,true,r.created_by,r.created_by); INSERT INTO public.inspection_work_order_items(work_order_id,repair_item_id) VALUES(w.id,c.repair_item_id); ELSE UPDATE public.inspection_repair_items SET inspection_section_id=vals.inspection_section_id,title_snapshot=vals.title_snapshot,description_snapshot=vals.description_snapshot,quantity=vals.quantity,unit=vals.unit,unit_price=vals.unit_price,contractor_unit_price=vals.contractor_unit_price,payer_role=vals.payer_role,payment_nature=vals.payment_nature,is_pending_quote=false,updated_by=r.created_by WHERE id=c.repair_item_id; INSERT INTO public.inspection_work_order_items(work_order_id,repair_item_id) VALUES(w.id,c.repair_item_id) ON CONFLICT(work_order_id,repair_item_id) DO NOTHING; END IF; END IF; END IF; UPDATE public.inspection_work_order_items SET quotation_paused=false WHERE work_order_id=w.id AND repair_item_id=c.repair_item_id; UPDATE public.quotation_work_order_changes SET decision=dec->>'decision',comment=left(dec->>'comment',2000),decided_at=now(),applied_at=CASE WHEN dec->>'decision'='accepted' THEN now() END WHERE id=c.id; INSERT INTO public.inspection_owner_feedback(inspection_id,report_version_id,repair_item_id,decision,comment,submitter_name) VALUES(r.inspection_id,r.report_version_id,c.repair_item_id,dec->>'decision',left(dec->>'comment',2000),trim(p_submitter_name)); END LOOP; UPDATE public.quotation_work_order_revisions SET status='resolved',submitter_name=trim(p_submitter_name),resolved_at=now(),updated_at=now() WHERE id=r.id; INSERT INTO public.inspection_audit_log(inspection_id,action,note) VALUES(r.inspection_id,'quotation_revision_resolved','Inversionista: '||trim(p_submitter_name)); RETURN jsonb_build_object('status','resolved'); END $$;
CREATE OR REPLACE FUNCTION public.protect_work_order_quotation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE iid uuid; BEGIN iid:=CASE WHEN TG_OP='DELETE' THEN OLD.inspection_id ELSE NEW.inspection_id END; IF current_user NOT IN ('postgres','service_role','supabase_admin') AND EXISTS(SELECT 1 FROM public.inspection_work_orders WHERE inspection_id=iid) THEN RAISE EXCEPTION 'use_quotation_revision'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_work_order_quotation BEFORE INSERT OR UPDATE OR DELETE ON public.inspection_repair_items FOR EACH ROW EXECUTE FUNCTION public.protect_work_order_quotation();
CREATE OR REPLACE FUNCTION public.protect_paused_work_item() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (OLD.quotation_paused OR OLD.is_archived) AND current_user NOT IN ('postgres','service_role','supabase_admin') THEN RAISE EXCEPTION 'quotation_change_awaiting_approval'; END IF; IF TG_OP='UPDATE' AND current_user NOT IN ('postgres','service_role','supabase_admin') AND (NEW.repair_item_id IS DISTINCT FROM OLD.repair_item_id OR NEW.work_order_id IS DISTINCT FROM OLD.work_order_id OR NEW.quotation_paused IS DISTINCT FROM OLD.quotation_paused OR NEW.is_archived IS DISTINCT FROM OLD.is_archived) THEN RAISE EXCEPTION 'not_authorized'; END IF; IF TG_OP IN ('INSERT','DELETE') AND current_user NOT IN ('postgres','service_role','supabase_admin') THEN RAISE EXCEPTION 'use_quotation_revision'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_paused_work_item BEFORE INSERT OR UPDATE OR DELETE ON public.inspection_work_order_items FOR EACH ROW EXECUTE FUNCTION public.protect_paused_work_item();
CREATE OR REPLACE FUNCTION public.protect_revision_work_order() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.quotation_work_order_revisions WHERE work_order_id=OLD.id AND status='awaiting_approval') AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.contractor_id IS DISTINCT FROM OLD.contractor_id) THEN RAISE EXCEPTION 'quotation_change_awaiting_approval'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_revision_work_order BEFORE UPDATE ON public.inspection_work_orders FOR EACH ROW EXECUTE FUNCTION public.protect_revision_work_order();
CREATE OR REPLACE FUNCTION public.guard_revision_publication() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.quotation_work_order_revisions WHERE inspection_id=NEW.inspection_id AND status='awaiting_approval') THEN RAISE EXCEPTION 'quotation_change_awaiting_approval'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_revision_publication BEFORE INSERT ON public.inspection_report_versions FOR EACH ROW EXECUTE FUNCTION public.guard_revision_publication();
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.submit_work_order(uuid,text,text,text,text,text)'::regprocedure) INTO def; IF position('AND status NOT IN (''done'',''not_done'')' in def)=0 THEN RAISE EXCEPTION 'unexpected_submit_definition'; END IF; def:=replace(def,'AND status NOT IN (''done'',''not_done'')','AND NOT is_archived AND status NOT IN (''done'',''not_done'')'); EXECUTE def; SELECT pg_get_functiondef('public.assign_work_order(uuid,uuid)'::regprocedure) INTO def; IF position('AND NOT r.is_pending_quote' in def)=0 THEN RAISE EXCEPTION 'unexpected_assign_definition'; END IF; def:=replace(def,'AND NOT r.is_pending_quote','AND NOT r.is_pending_quote AND NOT r.is_archived'); def:=replace(def,'INSERT INTO public.inspection_work_orders','IF EXISTS(SELECT 1 FROM public.inspection_work_orders WHERE inspection_id=p_inspection_id) THEN RAISE EXCEPTION ''use_quotation_revision''; END IF; INSERT INTO public.inspection_work_orders'); EXECUTE def; SELECT pg_get_functiondef('public.submit_owner_feedback(text,text,text,jsonb)'::regprocedure) INTO def; def:=replace(def,'BEGIN',E'BEGIN\n IF public.get_quotation_revision_public(p_property_id,p_token) IS NOT NULL THEN RAISE EXCEPTION ''use_revision_decisions''; END IF;'); EXECUTE def; SELECT pg_get_functiondef('public.get_published_report(text,text)'::regprocedure) INTO def; def:=replace(def,'''owner_feedback_locked'', v_locked','''owner_feedback_locked'', (v_locked OR public.get_quotation_revision_public(p_property_id,p_token) IS NOT NULL)'); EXECUTE def; END $$;
REVOKE ALL ON FUNCTION public.start_quotation_revision(uuid),public.save_quotation_revision_change(uuid,uuid,text,jsonb,text),public.discard_quotation_revision(uuid,uuid),public.submit_quotation_revision(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.start_quotation_revision(uuid),public.save_quotation_revision_change(uuid,uuid,text,jsonb,text),public.discard_quotation_revision(uuid,uuid),public.submit_quotation_revision(uuid,text) TO authenticated;
REVOKE ALL ON FUNCTION public.get_quotation_revision_public(text,text),public.submit_quotation_revision_decisions(text,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_quotation_revision_public(text,text),public.submit_quotation_revision_decisions(text,text,text,jsonb) TO anon,authenticated;